// Issue #7 per-feed calendar evidence: plain labels for what one response showed. Observed dates are not a publisher horizon,
// and records not seen in a newer response are never treated as cancelled.
// Text comes from src/sourceLabels.ts (tested): dates carry the year, and archives show capture and import separately.
function SourceEvidenceRows({source,evidence}:{source:any;evidence:any}){
 const latest=evidence.latestAttempt,success=evidence.latestSuccess,m=success?.measurement,revision=success&&revisionText(success);
 const unavailable=evidence.successEvidence==='earlier-check'?'Not measured for this earlier check; available after the next ordinary check.':evidence.successEvidence==='no-longer-retained'?'No longer retained; last-known records remain.':evidence.successEvidence==='unrecorded-intake'?'Not measured: the latest intake has no check record.':'None';
 return <>
  <dt>Latest check</dt><dd>{latest?latestCheckText(latest):source.health==='never checked'?'Never checked':'Earlier check; details not recorded'}</dd>
  <dt>Latest successful response</dt><dd>{success?`${m.accepted} accepted of ${m.returned} returned · ${m.parserRejects} rejected · ${m.duplicates} duplicate IDs · ${originText(success)}`:unavailable}{revision&&<><br/>{revision}</>}</dd>
  {success&&<><dt>Start dates seen in that response</dt><dd>{spanText(m.knownStarts,sourceDate)} with a clock time · {spanText(m.allDayStarts,sourceDay)} all-day · {m.unknownTime} unknown time · {m.recurringMasters} repeating (dates need checking). Not the publisher’s full date range.</dd>
  <dt>Listing order</dt><dd>{ORDER_LABELS[m.order]??'Not applicable'}</dd></>}
  <dt>Records</dt><dd>{evidence.retainedCount} kept from earlier checks · {evidence.currentResponseCount??'unknown'} in the latest successful response</dd>
  {success&&<><dt>Since previous check</dt><dd>{comparisonText(success.comparison)}</dd></>}
  {evidence.history.length>0&&<><dt>Recent checks</dt><dd><details className="decision-audit"><summary>{evidence.history.length} most recent</summary>{evidence.history.map((h:any)=><p key={h.attemptId}>{historyText(h)}</p>)}</details></dd></>}
 </>;
}
